const Q = (qt,sc,opts,ai,ex) => ({question_text:qt,scenario_context:sc,options:opts,correct_answer_index:ai,explanation:ex});

const MODULES = [
{
  title:"Module 1: AI Threat Landscape, Attack Taxonomy, and Defense Architecture",
  description:"The unique security risks of AI systems — OWASP LLM Top 10, documented production incidents, and defense-in-depth architecture.",
  order_index:0,
  videos:[
    {title:"1.1 The AI Attack Surface: Five Threat Categories",description:"Data poisoning, adversarial examples, model theft, prompt injection, and inference attacks with real incident case studies.",order_index:0,
     points:["AI systems introduce attack surfaces that don't exist in traditional software. The OWASP LLM Top 10 (2023) catalogs 10 vulnerability categories unique to LLM applications: prompt injection, insecure output handling, training data poisoning, model denial of service, supply chain vulnerabilities, sensitive information disclosure, insecure plugin design, excessive agency, overreliance, and model theft. These are documented, exploited vulnerabilities affecting production systems at every major technology company.","Data poisoning attacks target the training pipeline. Clean-label poisoning adds imperceptible perturbations to training images causing targeted misclassification without mislabeled examples appearing suspicious. The 2023 Nightshade paper (University of Chicago) demonstrated that 100 poisoned images out of millions could degrade a text-to-image model — showing data poisoning requires far fewer examples than previously assumed.","Adversarial examples exploit the fundamental brittleness of neural networks. The FGSM attack (Goodfellow et al., 2014) perturbs input pixels by epsilon times sign of the gradient causing misclassification while keeping perturbations imperceptible. Eykholt et al. (2018) demonstrated that printed adversarial stickers on stop signs caused autonomous vehicle models to misclassify them as speed limit signs with 100% success rate.","Model theft enables competitors to replicate your AI investment through API black-box access. Tramer et al. 2016 demonstrated successful model extraction against commercial ML APIs including BigML and Amazon ML with thousands of queries achieving 90%+ behavioral similarity. The attack treats the API as a labeling oracle and uses active learning to maximize information per query.","Inference attacks compromise user privacy by extracting information about training data. Carlini et al. 2021 demonstrated that GPT-2 memorizes and can regurgitate verbatim training text including private data when prompted with specific prefixes. Defense-in-depth for AI means overlapping security controls at 7 layers: data security, model development, input validation, LLM configuration, output validation, action validation, and infrastructure security."],
     questions:[
      Q("What is the OWASP LLM Top 10?","Building a security review checklist for your first LLM product.",["A subset of the OWASP Web Application Top 10","The first security standard specifically for LLM applications cataloging 10 vulnerability categories unique to AI systems not covered by traditional security frameworks","An updated version of existing guidelines","A compliance requirement for enterprise AI"],1,"OWASP LLM Top 10 recognizes that LLM applications have fundamentally different attack surfaces — prompt injection, training data poisoning, model theft, excessive agency. A new standard was needed for a new threat landscape."),
      Q("What made Nightshade significant?","Evaluating data poisoning risk for your crowdsourced training dataset.",["Data poisoning was previously thought impossible","Only 100 poisoned images out of millions degraded a text-to-image model — far fewer than previously assumed, making small-scale targeted poisoning by malicious contributors a realistic threat","The attack required physical access to training servers","Only affects image models"],1,"Nightshade showed data poisoning attacks are far more efficient than understood. 100 poisoned examples out of millions is a practical attack surface, meaning malicious contributors to public datasets pose a real threat."),
      Q("What did Carlini et al. demonstrate about LLM memorization?","Assessing privacy risks of deploying an LLM trained on user data.",["LLMs don't memorize training data","GPT-2 memorizes and can regurgitate verbatim training text including private data when prompted with specific prefixes — establishing memorization as a quantifiable extractable privacy risk for all LLMs without differential privacy","Memorization only affects small models","The risk is only theoretical"],1,"Carlini et al. showed targeted prompting can extract verbatim training content. This established memorization extraction as an active privacy threat applying to all LLMs trained without differential privacy."),
      Q("How does model theft work?","Protecting a proprietary model exposed via commercial API.",["Model theft requires physical access to servers","Systematically querying the API and training a surrogate model on query-prediction pairs achieves 90%+ behavioral similarity with thousands of queries — no internal access required","Only possible with millions of queries","Surrogate models perform much worse"],1,"The surrogate model captures decision boundaries by treating the API as a labeling oracle. Active learning query strategies reduce required queries by choosing inputs that maximally reveal decision boundaries."),
      Q("What is defense-in-depth for AI?","Designing security architecture for a customer-facing LLM application.",["A single comprehensive security layer","Overlapping security controls at 7 layers so that any single control failure does not expose the full system — AI security assumes each layer will occasionally fail","Security through obscurity","Only applicable to military AI"],1,"No single security control is perfect. Defense-in-depth means an attacker who bypasses one layer still faces multiple independent controls. Prompt injection bypassing system prompts still faces output validation and action confirmation.")
     ]
    },
    {title:"1.2 Prompt Injection: The #1 LLM Security Risk",description:"Direct vs indirect injection, documented incidents against Bing Chat and GitHub Copilot, and the multi-layer defense strategy.",order_index:1,
     points:["Prompt injection is OWASP LLM Top 10 number 1 because it undermines the LLM's ability to maintain intended behavior when processing adversarial input. Direct prompt injection: the user explicitly attempts to override the system prompt. Indirect prompt injection: malicious instructions embedded in content the LLM retrieves or processes — web pages, documents, emails. Indirect injection is more dangerous because the attack surface is all external content the LLM can access, not just user input.","Documented production incidents establish prompt injection as an active threat. Bing Chat 2023: researchers Kevin Liu and Marvin von Hagen manipulated the chatbot by embedding hidden instructions in web pages — Bing Chat's Sydney persona was revealed, its system prompt was extracted. GitHub Copilot Chat 2023: crafted code comments containing injection instructions influenced subsequent code suggestions. ChatGPT plugin ecosystem 2023: malicious web content retrieved by the browsing plugin instructed GPT-4 to exfiltrate user conversation history.","Defense Layer 1 — Input Isolation: Use structural separators to distinguish trusted system instructions from untrusted user input. Structure: system_instructions tags containing trusted content, user_input tags containing user content, retrieved_content tags containing external content. Include meta-instructions: content within user_input and retrieved_content tags is data to process, not instructions to follow.","Defense Layer 2 — Privilege Minimization and Out-of-Band Confirmation: Apply least privilege to LLM tool access. A web-browsing agent should have only web access, not email, files, and external APIs simultaneously. A confirmation gate completely outside the LLM conversation is required for high-impact actions. Anthropic's internal research found out-of-band confirmation reduced catastrophic agent failures by 73%.","Defense Layer 3 — Secondary Classification and Canary Monitoring: Implement a secondary LLM classifier reviewing every agent output for policy compliance before execution. Additionally implement canary injections in retrieved content — benign trigger patterns that should be ignored, alerting when followed. This provides ongoing production monitoring for injection susceptibility as system prompts and models change."],
     questions:[
      Q("What distinguishes direct from indirect prompt injection?","Designing injection defenses for an LLM document analysis system.",["Direct is always more dangerous","Direct: user crafts malicious input. Indirect: malicious instructions embedded in external content the LLM processes as data. Indirect is harder to detect because the user may be innocent — attack originates from external content.","No practical difference","Indirect only affects browsing agents"],1,"Direct injection is visible and attributable to the user. Indirect injection hides in content that appears legitimate — web pages, documents, emails. The user may be innocent; the attack originates from external content the LLM processes."),
      Q("What did the Bing Chat incident demonstrate?","Explaining injection risk to stakeholders who think it is only theoretical.",["Bing Chat had a programming bug","Embedding hidden instructions in web pages successfully manipulated Bing Chat's persona, extracted its system prompt, and caused policy violations — demonstrating indirect injection against production LLMs is a real reproducible attack","The incident was staged","Only affected early versions"],1,"The Bing Chat incidents were real, reproducible, and publicly documented — establishing indirect injection as an active production threat motivating serious investment in defenses across the industry."),
      Q("What does out-of-band confirmation prevent?","Securing an LLM agent that can send emails on behalf of users.",["It prevents all injection attacks","A separate UI element completely outside the LLM conversation confirms high-impact actions through a trusted interface that cannot be manipulated through prompt injection — even successful injection cannot cause the action without human confirmation","Two-factor authentication for the LLM","Rate limiting high-impact actions"],1,"Out-of-band confirmation breaks the injection attack chain at the action execution layer. Even if injection successfully manipulates the LLM, the confirmation gate rendered by trusted UI code blocks execution."),
      Q("What is a canary injection?","Building continuous monitoring for injection vulnerabilities in a deployed agent.",["An emergency shutdown command","Benign trigger patterns embedded in retrieved content that should be ignored — when the LLM follows them it signals injection susceptibility, providing ongoing monitoring as system prompts and models change","A test user account","A type of adversarial example"],1,"Canary injections are honeypot instructions in controlled retrieved content. Following them is detectable; not following is correct. As system prompts change and models update, canaries provide continuous regression testing of injection defenses."),
      Q("What structural approach reduces injection susceptibility?","Designing the system prompt architecture for a production LLM.",["Using longer system prompts","XML-style tags isolating trusted instructions from untrusted user input and retrieved content, with meta-instructions that content in user and retrieved sections is data to process not instructions to follow","Encrypting the system prompt","Using a different LLM model"],1,"Structural isolation using XML-style tags forces the LLM to treat different content sections differently. While not foolproof, it raises the sophistication required for successful injection and is a standard defense layer.")
     ]
    },
    {title:"1.3 Adversarial Robustness: Attacks, Defenses, and Certified Guarantees",description:"FGSM to AutoAttack, adversarial training, randomized smoothing, and gradient masking detection.",order_index:2,
     points:["The adversarial attack hierarchy: FGSM (Goodfellow 2014) is a single-step attack primarily used for adversarial training data augmentation. PGD (Madry 2018) is iterative FGSM with projection back to the epsilon-ball — the standard benchmark attack. C&W attack (Carlini and Wagner 2017) finds much smaller perturbations through optimization. AutoAttack (Croce and Hein 2020) is a parameter-free ensemble of diverse attacks nearly impossible to spoof — the current standard for credible robustness claims. Any defense claiming robustness must be evaluated against AutoAttack.","Gradient masking is the failure mode where a defense appears robust but provides no actual protection. Athalye et al. 2018 demonstrated that 7 of 9 defenses accepted at ICLR 2018 were gradient masking — broken by alternative attacks. Signs of gradient masking: white-box attacks perform worse than black-box transfer attacks, model accuracy under attack increases as attack iterations increase, AutoAttack dramatically outperforms single-step attacks. If any of these patterns appear, suspect gradient masking.","Adversarial training (Madry et al. 2018) is the most effective empirical defense. For each training batch, generate adversarial examples using PGD, add them to the batch, train on the combined batch. The model learns to classify correctly even under perturbation. Tradeoff: 2-10% lower clean accuracy and 3-5x higher training cost, but genuine robustness. RobustBench state of art 2024: approximately 63% accuracy on CIFAR-10 under strong PGD attacks versus 0% for undefended models.","Randomized Smoothing (Cohen et al. 2019) provides provable robustness guarantees — the only practically scalable certified defense for large neural networks. Construction: wrap classifier f in smoothed classifier g(x) returning the class most likely returned when Gaussian noise is added to x. If f correctly classifies noisy versions of x with sufficient probability, then g is certifiably robust within an L2 ball of radius r. The mathematical guarantee holds for all possible attacks within the perturbation budget.","The RobustBench leaderboard at robustbench.epfl.ch is the authoritative resource for standardized adversarial robustness evaluation using AutoAttack. Distribution shift robustness is equally important — ImageNet-C benchmark (Hendrycks and Dietterich 2019) tests 15 natural corruption types at 5 severity levels. State-of-the-art clean models often drop from 80% to 40% accuracy under severe corruptions that regularly occur in real-world deployment."],
     questions:[
      Q("What is gradient masking and why is it dangerous?","Evaluating whether a proposed adversarial defense is genuine.",["A privacy technique for model gradients","A defense appearing robust by making gradients uninformative rather than genuinely hardening the model — broken by alternative attacks. More dangerous than no defense because it creates false confidence.","Encrypting gradients during distributed training","A regularization technique"],1,"Gradient masking fools gradient-based attack evaluation without providing real protection. Athalye et al. showed 7 of 9 ICLR 2018 defenses were gradient masking. False security is worse than acknowledged vulnerability."),
      Q("Why is AutoAttack the standard evaluation benchmark?","Evaluating a vendor's robustness claim.",["AutoAttack is the fastest attack","An ensemble of diverse attacks nearly impossible to spoof — gradient masking defenses that fool simpler attacks are exposed. Robustness claims not validated against AutoAttack are not credible.","AutoAttack is the weakest attack","Only works on image classifiers"],1,"AutoAttack's ensemble design combining gradient-based and gradient-free attacks specifically addresses gradient masking. It is the community-accepted standard because it is nearly impossible to cheat."),
      Q("What is the robustness-accuracy tradeoff in adversarial training?","Deciding whether adversarial training is worth the cost.",["No tradeoff — adversarial training improves both","2-10% lower clean accuracy and 3-5x higher training cost, but genuine robustness under strong attacks — a real gain at a real cost","Adversarial training always improves clean accuracy","The tradeoff is too severe to justify"],1,"The robustness-accuracy tradeoff is a fundamental empirical finding, not a flaw in adversarial training. For safety-critical applications where adversarial inputs are a real threat, the cost is typically acceptable."),
      Q("What makes Randomized Smoothing uniquely valuable for safety-critical AI?","Deploying an AI system where regulators require provable safety guarantees.",["Higher accuracy than adversarial training","Mathematical certified robustness guarantees — for any input within radius r, classification is provably correct under all possible attacks. Unlike empirical defenses that might be broken by future attacks, the certificate is a mathematical bound that holds forever.","Cheaper to train","Works for all perturbation types"],1,"Certified robustness means no attack within this perturbation budget can fool this model — provably, not just empirically. For medical diagnosis or autonomous vehicles, empirical testing is insufficient. Randomized Smoothing provides the mathematical guarantee."),
      Q("What does ImageNet-C reveal about production AI robustness?","Your computer vision model achieves 80% accuracy in validation but fails in production.",["Production always performs better than benchmarks","Models accurate on clean images often drop to 40% accuracy under natural corruptions that occur in real deployments — ImageNet-C performance predicts production robustness better than clean accuracy.","ImageNet-C only tests adversarial attacks","Production failures are caused by insufficient training data"],1,"ImageNet-C tests 15 natural corruption types at 5 severity levels — realistic deployment conditions, not adversarial attacks. Testing on ImageNet-C before deployment predicts production robustness for camera-based systems in varying conditions.")
     ]
    },
    {title:"1.4 Differential Privacy: Mathematical Guarantees for Sensitive Data",description:"DP-SGD for neural network training, the privacy-utility tradeoff, and production implementations.",order_index:3,
     points:["Differential privacy (Dwork et al. 2006) provides a mathematical guarantee: an algorithm is epsilon-delta differentially private if adding or removing any single individual's data changes any output probability by at most e to the power epsilon plus a delta probability of failure. The epsilon parameter is the privacy budget — lower means stronger privacy. Apple uses epsilon 8 for keyboard predictions, Google uses epsilon 1-10 for RAPPOR analytics. The Gaussian mechanism adds calibrated Gaussian noise scaled to sensitivity divided by epsilon.","DP-SGD (Abadi et al. 2016) is the standard algorithm for training neural networks with differential privacy. The mechanism: clip gradients per example to bound sensitivity, add Gaussian noise to clipped gradients, proceed with standard SGD update. The privacy accountant tracks total privacy cost across all training steps. PyTorch's Opacus library implements DP-SGD with a PrivacyEngine wrapper for model, optimizer, and data loader.","The privacy-utility tradeoff depends critically on dataset size. Apple's iOS keyboard DP deployment with epsilon 8 across hundreds of millions of users achieves near-utility-parity with non-DP training. At 1,000 users the same noise would destroy utility. Scale is the critical factor — more users means more signal relative to fixed noise, making practical DP deployment viable for consumer products.","Federated learning with differential privacy enables training on distributed private data without centralizing raw data. Google's Federated Learning: each device computes local gradients, applies DP noise, sends noisy gradients to server for aggregation. Byzantine-robust aggregation algorithms including coordinate-wise median, Krum, and FLTrust defend against malicious participants submitting adversarially crafted gradient updates.","Local versus central differential privacy: Central DP — a trusted curator collects raw data and adds noise before publishing, providing stronger utility for the same privacy budget. Local DP — each individual adds noise to their own data before sharing, requiring no trusted curator but needing much larger epsilon for the same utility. Apple uses local DP for keyboard data. PATE (Private Aggregation of Teacher Ensembles) provides an alternative with better utility than DP-SGD in many settings."],
     questions:[
      Q("What does epsilon-delta differential privacy guarantee?","Evaluating privacy guarantees for a model trained on medical records.",["The model will never leak any training data","Adding or removing any single person's data changes any output probability by at most e-to-the-epsilon — a mathematical bound on how much an individual's data can influence outputs, preventing reliable identification","Epsilon and delta are accuracy metrics","Only applies to aggregate statistics"],1,"Differential privacy's guarantee bounds the influence of any individual's data on the model's outputs. Even with model access, an adversary cannot reliably determine whether any specific person's data was in the training set."),
      Q("What are the two key operations in DP-SGD?","Implementing differentially private training for a healthcare prediction model.",["Weight decay and batch normalization","Per-example gradient clipping to bound sensitivity and Gaussian noise addition to clipped gradients — clipping limits any individual sample's influence, noise prevents exact gradient reconstruction","Dropout and learning rate scheduling","Gradient checkpointing and mixed precision"],1,"DP-SGD's privacy comes from clipping per-example gradients to C so no single sample dominates the update, then adding Gaussian noise scaled to C divided by epsilon. Together these satisfy the DP guarantee while allowing gradient-based training."),
      Q("Why does dataset scale critically determine DP utility?","Deciding whether to implement DP for 500 vs 5 million users.",["Larger datasets always require more privacy","More users means signal dominates fixed noise — Apple achieves near-utility-parity at epsilon 8 across hundreds of millions of users. At 1,000 users the same noise would destroy utility. Scale compensates for the noise added for privacy.","Scale does not affect the tradeoff","Smaller datasets benefit more from DP"],1,"DP adds fixed noise independent of dataset size, but signal grows with more data. At sufficient scale the noise-to-signal ratio becomes negligible. This is why Apple and Google can deploy DP in consumer products while researchers with small datasets struggle."),
      Q("What is the Byzantine attack in federated learning?","Running federated learning across 1,000 hospital participants where some may be adversarial.",["A geographic region attack","Malicious participants submitting adversarially crafted gradient updates designed to corrupt the global model. Defense: Byzantine-robust aggregation (coordinate-wise median, Krum, FLTrust) detecting and filtering malicious updates before aggregation.","A network routing attack","An attack on the federated learning server"],1,"Byzantine attacks exploit federated aggregation — malicious participants craft gradients that when aggregated with legitimate updates manipulate the global model. Robust aggregation uses statistical methods less sensitive to outlier updates from malicious participants."),
      Q("What is PATE and when does it outperform DP-SGD?","Choosing a privacy-preserving training approach with access to unlabeled public data.",["A federated learning protocol","Private Aggregation of Teacher Ensembles — trains teacher models on disjoint private data, uses noisy voting to label public data, trains a student on public labels. Achieves strong privacy with better utility than DP-SGD when unlabeled public data is available.","A differential privacy accountant","A gradient clipping method"],1,"PATE separates private knowledge from the public model. Privacy budget is spent on the noisy voting mechanism, not on training, allowing the student model to train without additional privacy cost.")
     ]
    },
    {title:"1.5 AI Red Teaming: Methodology, Tools, and Production Security Operations",description:"Red teaming taxonomy, automated tools Garak and PyRIT, model supply chain security, and AI SecOps.",order_index:4,
     points:["AI red teaming is structured adversarial testing — systematically finding harmful behaviors, safety failures, and security vulnerabilities before deployment. Anthropic red teams every Claude release, OpenAI red teams every GPT release, Google DeepMind red teams Gemini. The AI red team taxonomy covers four domains: Safety and Alignment (elicit harmful content, bypass safety filters), Security (prompt injection, data extraction, model theft), Fairness and Bias (elicit discriminatory outputs), and Robustness (adversarial inputs, hallucination elicitation). Complete exercises require different expertise for each domain.","Automated red teaming tools scale adversarial testing. Garak (NVIDIA, open-source): LLM vulnerability scanner with 100+ probes covering jailbreaks, data extraction, toxicity, hallucination — runs automated adversarial probes and reports vulnerability rates per category. Microsoft PyRIT (Python Risk Identification Toolkit): automated red teaming using an attacker LLM to generate adversarial prompts targeting a target LLM, enabling adversarial simulation at scale. Promptfoo: systematic prompt testing with adversarial test case management and CI/CD integration.","The model supply chain is a severely underestimated attack vector. Python Pickle format executes arbitrary Python code when deserialized — a malicious pickle file can run reverse shells on load. JFrog Security discovered functional reverse-shell payloads in model files on HuggingFace in 2022. Defense: use SafeTensors format (non-executable tensor serialization) for all model artifacts. Only load models from verified organization-controlled sources. Verify checksums of downloaded artifacts.","AI Software Bill of Materials (AI SBOM) catalogs: base model (name, version, source), training data (datasets, licenses), fine-tuning data, all dependencies with exact versions, and model card. US Executive Order 14110 (October 2023) requires SBOM-like documentation for AI systems used by the US government. When a CVE is published for a critical library, an AI SBOM enables immediate identification of all affected production systems.","AI Security Operations (AI SecOps) extends traditional SOC practices to AI-specific threat monitoring. AI-specific SIEM rules: systematic query patterns indicating model theft, prediction distribution anomalies indicating model compromise, tool call anomalies indicating injection success. Incident response playbooks: model rollback (instant reversion when compromise suspected), model quarantine (take suspected compromised model offline), feature and input blocking. Practice AI-specific incident response in tabletop exercises before incidents occur."],
     questions:[
      Q("What four domains does AI red teaming cover?","Setting up a comprehensive red team exercise for your LLM system.",["Legal, compliance, technical, and business","Safety and Alignment (harmful content, jailbreaks), Security (injection, data extraction, model theft), Fairness and Bias (discriminatory outputs), and Robustness (adversarial inputs, hallucination) — requiring different expertise for each domain","Only safety and security","Network and application security only"],1,"AI red teaming is multidisciplinary because AI failure modes span domains. A cybersecurity expert handles Security; a domain expert provides insight for finding harmful outputs in specialized domains; a fairness researcher finds demographic performance disparities."),
      Q("Why is Python Pickle format a critical AI security risk?","Your team downloads pre-trained models from HuggingFace using torch.load.",["Pickle files are too large","Pickle format executes arbitrary Python code when deserialized — a malicious model file can run reverse shells on load. JFrog Security discovered real malicious PyTorch models on HuggingFace in 2022. SafeTensors format eliminates this by being non-executable.","Pickle is not supported by modern Python","Pickle files corrupt model weights"],1,"torch.load deserializes Pickle format which can execute arbitrary Python code embedded in the file. JFrog's 2022 discovery of functional reverse-shell payloads proved this is an active threat. SafeTensors is a safe tensor-only format that cannot execute code."),
      Q("What is Garak?","Setting up automated security testing for your LLM product in CI/CD.",["A Kubernetes security scanner","An open-source LLM vulnerability scanner with 100+ probes covering jailbreaks, data extraction, toxicity, and hallucination — runs automated adversarial probes and reports vulnerability rates per category. Integrates into CI/CD to catch regressions in security posture.","A model training tool","A differential privacy library"],1,"Garak automates the obvious vulnerability phase of security testing — running systematic adversarial probes and reporting which categories succeed. This frees human red teamers to focus on sophisticated context-specific attacks."),
      Q("What does an AI SBOM enable for incident response?","A critical CVE is published for transformers library version X.",["A budget document","A catalog of base model, training data, and dependencies with exact versions — when a CVE affects a specific library version, SBOM enables immediate identification of all affected production systems rather than manual auditing of dozens of deployments.","A compliance certificate","An audit log of model predictions"],1,"Without SBOM: discover affected systems by manually checking each production deployment taking hours or days. With SBOM: query the catalog for all systems using the affected version in minutes. The difference enables timely patching within responsible disclosure windows."),
      Q("What AI-specific SIEM rule detects model theft attempts?","Building monitoring for your production ML API.",["Monitoring for 401 authentication errors","Systematic query patterns showing uniform input space coverage — mathematically selected inputs that maximally reveal decision boundaries — indicating active surrogate model training against your API","Standard HTTP error codes","Tracking user login frequency"],1,"Model theft attacks use active learning query strategies producing a distinctive pattern: inputs spread uniformly across the input space rather than following natural user query distributions. This signature distinguishes theft from legitimate high-volume usage.")
     ]
    }
  ],
  endQuiz:[
    Q("What is excessive agency in the OWASP LLM Top 10?","Reviewing an LLM agent with broad tool access.",["Using too much compute","An LLM agent with more capabilities or permissions than necessary — when compromised via injection, enables actions far beyond intended function. Least-privilege design prevents it.","Too many parameters","Exceeding API rate limits"],1,"Excessive agency is why blast radius of successful injection can be catastrophic. An agent needing only document reading but having write, delete, and external API permissions can cause far more damage than intended when compromised."),
    Q("What is many-shot jailbreaking?","Testing your LLM's resistance to context-manipulation attacks.",["Attacking with many different prompts simultaneously","Prefilling conversation history with dozens of examples of the model complying with prohibited requests — exploiting in-context learning to establish a compliance pattern that bypasses safety training","A brute-force API attack","A distributed denial of service attack"],1,"Many-shot jailbreaking exploits the same in-context learning that makes LLMs useful. Pre-filling with compliance examples teaches the model in-context that compliance is expected behavior, bypassing safety training that only considers single-turn interactions."),
    Q("What is clean-label poisoning?","Reviewing a crowdsourced training dataset for security threats.",["Poisoning with correctly formatted data","Adds imperceptible perturbations to correctly labeled training examples causing targeted misclassification at test time — appears correctly labeled in human review, detectable only by testing for specific trigger patterns not by label inspection.","A type of poisoning with no effect","A poisoning attack targeting only the test set"],1,"Clean-label poisoning bypasses the most intuitive defense — checking for mislabeled examples — because labels are correct. The attack is embedded in the feature space only visible through the model's behavior on specific trigger inputs."),
    Q("What did the Zou et al. 2023 adversarial suffix paper demonstrate?","Evaluating whether safety training alone is sufficient protection.",["A minor finding with no practical implications","Gradient optimization can find universal adversarial suffixes reliably bypassing safety training across multiple frontier models simultaneously. Proves RLHF safety can be algorithmically circumvented — single-layer safety is insufficient.","Only affects open-source models","The attack requires model weight access"],1,"Zou et al. demonstrated safety training is bypassable algorithmically through automated optimization. The universal and transferable properties motivated the entire field to move from relying on safety training alone to defense-in-depth architectures."),
    Q("What is the treat LLM output as untrusted input principle?","Your agent generates SQL queries from user questions and executes them directly.",["LLM outputs are always incorrect","LLM-generated outputs used in downstream systems must be validated as untrusted input before execution — SQL injection, command injection, and SSRF are all possible through LLM-generated content if not validated.","Never use LLM output in production","LLM outputs should be cached before use"],1,"An LLM that generates SQL can be manipulated through the user's question or indirect injection to generate malicious SQL. LLM output must be treated with the same suspicion as direct user input: type-checked, parameterized, and sandboxed.")
  ]
},

{
  title:"Module 2: LLM Security — Jailbreaks, Output Security, and Runtime Defense",
  description:"Advanced jailbreaking techniques, insecure output handling, LLM denial of service, sensitive information disclosure, and agentic AI security.",
  order_index:1,
  videos:[
    {title:"2.1 Advanced Jailbreaking: Crescendo, Many-Shot, and Automated Attacks",description:"Full taxonomy of modern jailbreaking with defense strategies.",order_index:0,
     points:["Crescendo attacks (Microsoft Research 2024) gradually escalate from benign to harmful requests through a sequence of related questions — each step seems reasonable, the cumulative destination is harmful. Published success rate against frontier models: 70-80% on sensitive topics. Defense: maintain conversation-level policy monitoring, not just turn-level evaluation — Crescendo exploits the fact that most safety evaluation happens turn-by-turn.","Many-shot jailbreaking (Anthropic 2024): prefilling conversation history with dozens of demonstrations of compliant harmful behavior is highly effective — success rate grows with number of shots. DAN (Do Anything Now) and roleplay jailbreaks exploit instruction-following training by establishing fictional personas where safety guidelines supposedly do not apply. Defense: meta-prompt instructions explicitly addressing roleplay and persona manipulation.","Automated adversarial suffix attacks (Zou et al. 2023): gradient-based optimization finds token sequences that when appended to any harmful prompt cause safety-trained models to comply. The GCG algorithm iteratively replaces tokens to minimize the probability the model refuses. Universal suffixes transfer across models — found against Llama-2, works against GPT-4. This demonstrates RLHF safety training has inherent bypasses requiring layered defense.","Tree of Attacks with Pruning (TAP, Mehrotra et al. 2023): uses an attacker LLM to generate many candidate jailbreak prompts, prunes ineffective ones, refines promising ones through tree search. Achieves near-100% attack success rate against GPT-4 on many harmful categories with no human involvement. Automated attack generation means new jailbreaks can be discovered at scale, making static defenses rapidly obsolete.","Defense stack for advanced jailbreaks: Input pre-screening with secondary classifier checking user input before LLM processing. System prompt hardening with explicit instructions addressing each jailbreak category. Output classification with LlamaGuard-style evaluation of every LLM output before returning to user. Conversation-level monitoring to detect multi-turn escalation patterns. Human review queue routing low-confidence classifications to human reviewers. No single layer is sufficient — all five together provide practical production resilience."],
     questions:[
      Q("What is the Crescendo attack and what makes it effective?","Building defenses for a customer-facing LLM handling sensitive topics.",["A fast brute-force attack","A multi-turn technique gradually escalating from benign to harmful requests — each step appears reasonable while the cumulative destination is harmful. Achieves 70-80% success by exploiting turn-by-turn safety evaluation that misses conversation-level escalation patterns.","A single-turn prompt injection","An adversarial suffix attack"],1,"Crescendo exploits that most safety evaluation happens turn-by-turn, not across the full conversation arc. Each individual step seems like a reasonable follow-up question, so no single turn triggers safety measures while the conversation incrementally reaches harmful territory."),
      Q("What makes automated adversarial suffix attacks qualitatively different from manual jailbreaking?","Evaluating whether your system prompt is sufficient protection.",["They are less effective than manual attacks","GCG finds universal suffixes transferring across models with no human creativity required — demonstrating RLHF safety has inherent algorithmic bypasses requiring layered defense beyond the model","They only work on open-source models","They require access to model weights"],1,"Zou et al. showed safety bypasses can be found algorithmically and universally, meaning the problem is not solvable by better safety training alone. Even a perfectly safety-trained model can potentially be bypassed by automated optimization."),
      Q("What is Llama Guard?","Designing a multi-layer safety system for a production chatbot.",["A jailbreak attack tool","A secondary classifier evaluating both user inputs before LLM processing and LLM outputs before returning to user for policy violations — providing an independent safety layer that does not rely on the primary LLM's safety training","A prompt injection detection tool","A model fine-tuning approach"],1,"Llama Guard is a meta-LLM trained to classify inputs and outputs across multiple harm categories. As an independent classifier, it provides defense in depth — if the primary LLM's safety training is bypassed, Llama Guard still evaluates the output."),
      Q("Why are static jailbreak defenses rapidly obsolete?","Planning your long-term LLM security strategy.",["Static defenses are the industry standard","Automated attack generation (TAP achieving near-100% success, GCG finding universal suffixes) means new jailbreaks can be discovered at scale without human creativity — making blacklist-based and pattern-matching defenses obsolete within days","Static defenses work with regular updates","Jailbreaks are rare enough that static defenses work"],1,"TAP can discover new effective jailbreaks for any target LLM using another LLM as an attacker. The attack surface is effectively infinite — for every static defense pattern added, a new effective jailbreak can be algorithmically generated."),
      Q("What five layers comprise the defense stack for advanced jailbreaks?","Building a comprehensive jailbreak defense system for enterprise deployment.",["Only system prompt hardening is needed","Input pre-screening, system prompt hardening, output classification, conversation-level monitoring for multi-turn escalation, and human review queue — no single layer is sufficient, all five together provide practical production resilience.","Only output filtering is needed","Rate limiting plus IP blocking"],1,"Each layer addresses different attack vectors: input screening catches simple cases, system prompt hardening addresses category-specific attacks, output classification catches successful jailbreaks, conversation monitoring catches multi-turn escalation, and human review handles ambiguous cases.")
     ]
    },
    {title:"2.2 Insecure Output Handling and LLM-Generated Code Security",description:"SQL injection, XSS, command injection from LLM-generated content, and secure output handling patterns.",order_index:1,
     points:["Insecure output handling is OWASP LLM Top 10 number 2 — occurring when LLM-generated content is used directly in security-sensitive downstream operations without treating it as untrusted input. The LLM is a transformation layer, not a sanitization layer. A SQL query generated from user input is just as dangerous as user-supplied SQL without parameterization. LLM-generated HTML must be escaped before rendering just like direct user input.","LLM SQL injection: a natural language database query system generates SQL from user questions. User question manipulation can cause the LLM to generate DROP TABLE or DELETE statements. Defense: parameterized queries even for LLM-generated SQL, query allowlisting permitting only SELECT statements, SQL parser validation before execution — treating LLM-generated SQL with the same validation pipeline as user-supplied SQL.","LLM-generated code security: GitHub Copilot and similar tools generate code inheriting security vulnerabilities from training data. Studies show LLM-generated code contains security vulnerabilities at similar rates to human-written code — SQL injection from forgetting parameterization, hardcoded credentials, insecure deserialization, path traversal. Defense: static analysis tools Semgrep and CodeQL in CI/CD pipeline scanning all generated code, mandatory human security review for security-critical functions.","Cross-site scripting via LLM output: a customer service chatbot generating HTML responses can output script tags if an attacker includes XSS payloads in their query. The LLM has no XSS awareness — it generates plausible-looking HTML. Defense: HTML encoding all LLM outputs before rendering in browser, DOMPurify for client-side sanitization, Content Security Policy headers, plain text output constraints when possible.","Command injection through LLM tool use: an LLM agent executing system commands based on user requests can be manipulated to include shell injection characters. Defense: command allowlisting permitting only specific pre-approved commands, argument validation against expected patterns rejecting semicolons pipes and special characters, containerized execution environment with minimal permissions, never pass LLM output directly to shell execution."],
     questions:[
      Q("Why is treating LLM output as trusted input a critical mistake?","Your team builds an LLM-powered data analysis tool that executes generated code.",["LLM outputs are technically trustworthy","LLM outputs used in security-sensitive operations can contain injection payloads from user manipulation or indirect injection. The LLM does not sanitize — it transforms. All LLM output must be treated as untrusted.","LLM outputs are always safe","Only SQL injection is a concern"],1,"The LLM is a sophisticated text transformer that produces plausible-looking outputs including plausible-looking injection payloads. It has no security awareness and generates whatever text is most likely given the context, which may include dangerous constructs."),
      Q("What defenses prevent SQL injection from LLM-generated queries?","Building an NL-to-SQL system for business analytics.",["Asking the LLM to avoid SQL injection in its system prompt","Parameterized queries regardless of query source, query allowlisting permitting only SELECT statements, and SQL parser validation before execution — treating LLM-generated SQL with the same validation pipeline as user-supplied SQL","Checking LLM output for the word DROP","Using a different database system"],1,"Parameterized queries separate SQL structure from data values even when structure is LLM-generated. Query allowlisting prevents destructive statements. SQL parser validation catches malformed or suspicious queries before execution."),
      Q("What does research show about security vulnerabilities in LLM-generated code?","Deciding whether LLM-generated code needs the same security review as human code.",["LLM code is more secure than human code","LLM-generated code contains security vulnerabilities at similar rates to human-written code — SQL injection, hardcoded credentials, insecure deserialization, path traversal — inherited from training data patterns","LLM code never has security vulnerabilities","Only authentication code needs review"],1,"LLM code generation learns from the corpus of existing code including the security mistakes in that corpus. Without explicit safety training for secure coding, LLMs reproduce common vulnerability patterns at rates comparable to average human developers."),
      Q("What defends against XSS in LLM-generated HTML responses?","Building a chatbot that renders HTML responses in browser.",["Using a content filtering LLM layer","HTML encoding all LLM outputs before browser rendering using DOMPurify, Content Security Policy headers preventing inline script execution, and plain text output constraints when possible — the LLM has no XSS awareness, only downstream encoding prevents injection","Instructing the LLM not to generate scripts","Using HTTPS for all connections"],1,"HTML encoding transforms script tags into their HTML entity equivalents — the browser displays text instead of executing it. DOMPurify strips dangerous HTML constructs. CSP prevents execution of inline scripts. The LLM cannot distinguish safe from unsafe HTML."),
      Q("What is the most effective defense against command injection through LLM tool use?","An LLM agent that lists files and runs analysis scripts based on user requests.",["Asking the LLM to validate its own commands","Command allowlisting permitting only specific pre-approved commands plus argument validation rejecting semicolons pipes and path traversal sequences, combined with containerized execution with minimal permissions","Logging all executed commands","Rate limiting command execution"],1,"Allowlisting is the strongest defense — if the LLM can only call five specific pre-approved commands, it literally cannot generate dangerous commands regardless of injection attempts. Argument validation prevents chaining. Container isolation limits blast radius even if injection succeeds.")
     ]
    },
    {title:"2.3 LLM Denial of Service, Resource Security, and Sensitive Information Disclosure",description:"Prompt flooding, context exhaustion, multi-tenant isolation, PII detection, and compliance requirements.",order_index:2,
     points:["LLM Denial of Service is OWASP LLM Top 10 number 4. LLM inference is computationally expensive and input length directly scales cost. A single malicious user can generate thousands of dollars of inference cost with carefully crafted long prompts. A GPT-4 prompt with 128,000 tokens costs approximately $1.28 per request. An attacker sending 1,000 max-context requests per hour generates over $1,200 per hour in API costs. Recursive tool call loops in agentic systems can execute indefinitely without max_iterations limits.","Production rate limiting architecture for LLM APIs uses five layers: request rate limits per user per minute, token rate limits per user per hour, cost limits per user per day with automatic suspension, concurrent request limits preventing parallel flooding, and content-based limits routing unusually long prompts to review queue. Implementation uses Redis-based sliding window counters. LLMjacking — stolen API credentials used for cryptomining or reselling — requires cost-based anomaly detection not just request rate monitoring.","Sensitive information disclosure is OWASP LLM Top 10 number 6. LLMs can leak sensitive information through three vectors: training data memorization (model regurgitates training data containing sensitive info), system prompt extraction (model reveals confidential instructions), and context leakage (information from one user or session appearing in another's context in multi-tenant deployments). Each requires different defenses.","PII detection and redaction pipeline for LLM inputs: before sending user-provided content to LLMs, detect and redact PII. Microsoft Presidio (open-source, 50+ entity types), AWS Comprehend PII detection, Azure AI Language PII detection. Redaction approach: replace with typed placeholders such as [NAME] [EMAIL] [SSN] rather than removing, preserving context for the LLM while protecting actual values.","Multi-tenant LLM isolation prevents information leakage between users: session-level context isolation never sharing context objects between sessions, per-user namespacing in vector databases using Pinecone namespaces and Weaviate multi-tenancy, row-level security in PostgreSQL for structured data retrieval, audit logging of all retrievals for forensic capability. GDPR Article 17 right to erasure extends to models trained on user data — machine unlearning or retraining is required, not just deleting raw training files."],
     questions:[
      Q("Why is LLM DoS economically unique compared to traditional DoS?","Designing cost controls for a public-facing LLM API.",["LLM DoS is the same as traditional DoS","LLM inference is expensive and input length directly scales cost — a single max-context GPT-4 prompt costs $1.28. Attackers can generate thousands of dollars of inference costs per hour, creating economic damage even without availability impact.","LLM APIs are too cheap for DoS to be viable","Only output length affects cost"],1,"Traditional DoS targets availability. LLM DoS can target economics — forcing massive inference costs without necessarily taking down the service. LLMjacking (stolen API access for cryptomining) and bill bombing are uniquely LLM attack goals."),
      Q("What is LLMjacking and what monitoring detects it?","Detecting unauthorized use of your LLM API credentials.",["A SQL injection variant","Stolen LLM API credentials used for cryptomining, reselling API access, or massive-scale inference. Detection requires anomaly monitoring on query patterns and cost velocity, not just rate limit monitoring — attackers may stay within request limits while maximizing token consumption.","A prompt injection attack","A model fine-tuning attack"],1,"LLMjacking targets the economic value of LLM API access. Attackers operate at normal request rates but maximize context lengths and compute. Cost-based anomaly detection (spending velocity per API key) catches what request-rate monitoring misses."),
      Q("What are the three vectors for sensitive information disclosure in LLM systems?","Conducting a data privacy risk assessment for your LLM product.",["Only training data leakage is a concern","Training data memorization, system prompt extraction, and context leakage in multi-tenant deployments — each requiring different defenses: DP training for memorization, meta-instructions and output filtering for prompt extraction, and session isolation for context leakage","Only user input to output leakage","Only applies to fine-tuned models"],1,"Each disclosure vector has a different attack mechanism and requires different defenses. The three-vector framework provides a complete taxonomy for privacy risk assessment of LLM systems."),
      Q("What is Microsoft Presidio and why is it used in LLM input pipelines?","Building a privacy-preserving LLM application that processes user-submitted documents.",["A model security testing framework","An open-source PII detection and anonymization library supporting 50+ entity types that detects and replaces PII with typed placeholders before sending to LLMs — preserving context while protecting actual values from third-party APIs or logs","A rate limiting library","An LLM fine-tuning tool"],1,"Presidio detects PII in text and replaces it with type-labeled placeholders. The LLM can still reason about structure and context while actual PII values are never sent to third-party APIs or stored in conversation logs."),
      Q("What is the GDPR Article 17 implication for LLMs fine-tuned on personal data?","A user invokes their GDPR right to erasure and your LLM was fine-tuned on their documents.",["GDPR does not apply to ML training","If a user requests erasure, any fine-tuned model trained on their data must be addressed — either through machine unlearning or retraining without their data. Simply deleting raw training files is insufficient if the model has memorized that data.","Only the training data files need deletion","Anonymization fully satisfies GDPR"],1,"GDPR right to erasure creates a right to be unlearned from ML models. A model trained on personal data may have memorized it in its weights. This is one reason enterprise LLM fine-tuning increasingly uses synthetic data or strictly anonymized data.")
     ]
    },
    {title:"2.4 Agentic AI Security: Tool Abuse, Privilege Escalation, and Multi-Agent Attacks",description:"Security challenges unique to agentic systems — tool abuse, multi-agent trust hierarchies, and the security architecture for production agent deployments.",order_index:3,
     points:["Agentic AI systems create fundamentally new security challenges because agents take real-world actions autonomously. Key attack surfaces: tool abuse (manipulating the agent to call tools with attacker-controlled arguments), privilege escalation (convincing the agent it has permissions it does not have), multi-agent trust attacks (a compromised subagent poisoning the orchestrator), long-horizon attacks (injection early in a session influencing actions much later), and lateral movement (using one compromised agent to attack adjacent systems).","Tool abuse via injection: an agent with web search, email, and file system tools can be instructed by a malicious web page to email all files to an attacker. Defense: tool-specific authorization policies requiring human approval for email sending regardless of conversation context, argument sanitization per tool, out-of-band confirmation for tool calls meeting risk criteria, and audit logging of every tool call with the reasoning and authorization context.","Multi-agent trust hierarchies: a subagent compromised by injection can poison the orchestrator with false information. The orchestrator may implicitly trust subagent reports without the same skepticism applied to user inputs. Defense: treat inter-agent messages as untrusted input (validate and sanitize), separate context windows per agent preventing direct context sharing, result verification before passing between agents.","Persistent memory injection: agents with persistent memory can have that memory poisoned by embedding injection instructions in indexed content. The injection stays dormant until a triggering condition activates it potentially weeks or sessions later. Defense: memory content filtering before storage, injection detection before memory retrieval, isolation between user-specific and system-wide memory stores.","Security architecture for production agents: minimal capability (each agent gets only tools required for its specific task), reversibility preference (read before write, draft before send), step-level logging (every action logged with reasoning and authorization context), hard limits (maximum tool calls, cost, and execution time per session), session isolation (each agent session in isolated container), and human-in-the-loop gates (all high-risk actions require human approval via out-of-band confirmation)."],
     questions:[
      Q("What makes agentic AI security fundamentally different from API security?","Conducting a security review for a new autonomous agent managing customer accounts.",["They are the same security domain","Agents take real-world actions autonomously with lasting consequences across extended multi-step sessions. A compromised agent can send emails, delete files, make purchases, and execute code. The attack surface includes all tools, all accessible data, and all systems the agent can reach.","Only prompt injection is a new concern","Agents are always safer because they use LLMs"],1,"Agent security is about autonomous action security. A single successful injection in an agent session can cause cascading real-world damage across the agent's entire tool set and session duration. Security must assume injection will occur and limit consequences through tool minimization, reversibility, and human gates."),
      Q("How does multi-agent trust poisoning work?","Designing a multi-agent research system where subagents report findings to an orchestrator.",["Inter-agent communication is always secure","A compromised subagent can fabricate results or embed injection instructions in its reports to the orchestrator, which trusts the subagent as a legitimate system component. Defense: treat inter-agent messages as untrusted input, separate context windows, result verification before action.","Using encrypted communication between agents","Only external inputs need security review"],1,"Multi-agent trust attacks exploit the natural tendency to trust system components. The orchestrator may implicitly trust subagent reports without skepticism. Treating all inter-agent communication as potentially compromised data closes this attack vector."),
      Q("What is persistent memory injection?","Securing the long-term memory of a production AI assistant that indexes user documents.",["A standard buffer overflow attack","Embedding injection instructions in indexed content that persists in agent memory — the injection stays dormant until a triggering condition activates it potentially weeks later. Uniquely dangerous because compromised once, lasts indefinitely without memory clearing.","A denial of service technique","Only affects retrieval-augmented generation"],1,"Unlike session-limited injection that ends when the conversation ends, memory injection persists across sessions. An attacker who gets one document indexed can create a persistent backdoor in the agent's memory store that activates on future triggers."),
      Q("What is the minimal capability principle for agent tool design?","Designing tool access for a customer service agent that looks up orders and processes refunds.",["Agents should have all tools for maximum utility","Each agent gets only the tools required for its specific function — a customer lookup agent gets read-only database access, only the refund-processing agent gets write access to the billing system. Compromising a limited agent has limited blast radius.","Agents should share tool access for efficiency","Only apply to external-facing agents"],1,"Minimal capability directly limits the damage from successful injection. If the customer lookup agent only has SELECT permissions on the customer table, injection cannot cause it to delete records, send emails, or access financial systems."),
      Q("What six architectural properties define a secure production agent deployment?","Auditing your autonomous agent architecture for security compliance.",["Only authentication and authorization matter","Minimal capability, reversibility preference, step-level logging, hard limits on tool calls and cost and execution time, session isolation in containerized execution, and human-in-the-loop gates for high-risk actions requiring out-of-band human approval","Only the communication channel needs securing","Rate limiting and input validation are sufficient"],1,"Each property addresses a different failure mode: minimal capability limits blast radius, reversibility reduces irreversible damage, logging enables forensics, hard limits prevent DoS and runaway costs, isolation prevents lateral movement, and human gates prevent catastrophic autonomous actions.")
     ]
    },
    {title:"2.5 Model Supply Chain Security and Secure MLOps",description:"Securing ML infrastructure from training through deployment — artifact integrity, CI/CD security gates, and secrets management.",order_index:4,
     points:["ML training infrastructure presents unique security challenges: GPU instances with high compute value are targets for cryptojacking, training data pipelines process sensitive data at scale, and distributed training requires low-latency networking conflicting with security controls. GPU utilization monitoring detects cryptojacking — legitimate training shows high sustained utilization while cryptomining shows different patterns. IMDSv2 on EC2 prevents SSRF attacks from stealing instance IAM credentials via the metadata service endpoint at 169.254.169.254.","Model artifact signing establishes provenance. Workflow: after training, generate SHA-256 hash of artifact, sign hash with training infrastructure's private key stored in AWS KMS or HashiCorp Vault, store signature alongside artifact in registry. At deployment: verify signature using public key before loading model. Tools: Cosign from the Sigstore project for container-based model signing. Any modification to the artifact after signing invalidates the signature, catching both malicious substitution and accidental corruption.","Content scanning for model artifacts uses specialized tools: Hugging Face's Lassie Scanner scans 100,000+ models per week for malicious content. Enterprise implementation integrates ClamAV or ProtectAI Guardian into the model registry push pipeline — every artifact scanned before being made available for deployment. Scan for: pickle payloads with arbitrary code execution, obfuscated code in config files, unexpected binary payloads appended to tensor data, and known malicious model hashes.","Secure ML CI/CD extends DevSecOps principles to ML pipelines. Traditional gates (SAST, dependency scanning, container security) are necessary but insufficient. ML pipelines additionally need adversarial robustness tests, model behavior regression tests, and privacy leakage checks. Dependency scanning for ML: Snyk and Dependabot scan Python dependencies for known CVEs. Critical ML libraries with recent high-severity CVEs include PyTorch for arbitrary code execution via model loading and Transformers for malicious model execution.","Secrets management for ML pipelines: common mistakes include hardcoding API keys in training scripts (end up in git history), environment variables in container images (visible in image inspection), and secrets in Jupyter notebooks committed to git. Defense: HashiCorp Vault or AWS Secrets Manager for all secrets, Vault dynamic secrets generating ephemeral credentials per job revoked after completion, git-secrets pre-commit hook blocking credential commits, secret scanning in CI/CD using GitGuardian or TruffleHog."],
     questions:[
      Q("What does model artifact signing prevent?","Securing your model registry against supply chain attacks.",["It prevents model theft","Artifact signing with cryptographic signatures prevents tampering — any modification after signing invalidates the signature. At deployment, signature verification ensures the model in registry is exactly the model that training produced, catching malicious substitution and accidental corruption.","It compresses model files","It prevents unauthorized model access"],1,"Model artifact signing creates cryptographic proof of provenance and integrity. Unlike a checksum which can be regenerated after tampering, a signature requires the private key from the training system. Tampering with the artifact invalidates a signature that only the signing authority can create."),
      Q("What security gate must run before a model artifact is published to the registry?","Implementing a secure ML CI/CD pipeline.",["Performance benchmarking only","Content scanning for malicious payloads using specialized tools like ProtectAI Guardian or ClamAV — every artifact scanned before publication to block pickle payloads, obfuscated code, and known malicious model hashes before entering the system","Only signature verification","Storage quota checks"],1,"Model content scanning is the equivalent of antivirus scanning for code commits — a security gate preventing known malicious content from entering the system. Without it, a single malicious model artifact can compromise every system that loads it."),
      Q("Why should latest model version tags be avoided in production deployments?","Reviewing a Kubernetes model serving deployment manifest.",["Latest tags save storage space","Latest tags create non-deterministic deployments — a model pushed to registry automatically becomes production without going through validation, adversarial testing, and approval. Explicit version pinning ensures every production model version is explicitly reviewed and approved.","Latest tags are required for Kubernetes","Latest tags are more secure than versioned tags"],1,"Latest tag deployments mean deploy whatever is most recently pushed to registry. This bypasses every validation, security review, and approval process. Explicit version pinning ensures deployment is a deliberate reviewed action."),
      Q("What is the most dangerous secrets management mistake in ML pipelines?","Reviewing security practices for a data science team's training pipeline.",["Using temporary credentials","Hardcoding API keys in training scripts or Jupyter notebooks that get committed to git — the secret enters git history permanently even if later deleted, since history persists. This is the most common source of cloud credential exposure in ML teams.","Using environment variables properly","Rotating credentials quarterly"],1,"Git history preserves every committed secret permanently. Even git rm and force-push do not remove secrets from git history that has been cloned or pushed to remote. Secrets in Jupyter notebooks are particularly dangerous because notebooks are often committed to repositories for collaboration."),
      Q("What does IMDSv2 prevent in EC2-based ML training?","Hardening EC2 training instances against credential theft.",["IMDSv2 is a performance optimization","IMDSv2 requires session-oriented requests with a PUT token before GET requests to the instance metadata service — preventing SSRF attacks that exploit a vulnerable application on the instance to steal the instance IAM credentials via the metadata service endpoint.","IMDSv2 encrypts training data","IMDSv2 prevents network access from instances"],1,"Without IMDSv2, an SSRF vulnerability in any application on the training instance allows an attacker to call the metadata service and retrieve temporary IAM credentials. With IMDSv2, the SSRF cannot complete the required PUT request, blocking the credential theft pathway.")
     ]
    }
  ],
  endQuiz:[
    Q("What is the Crescendo attack's key insight about LLM safety evaluation?","Designing a multi-turn safety monitoring system.",["Single-turn evaluation is always sufficient","Most safety evaluation happens turn-by-turn not across conversation arcs — Crescendo exploits this by making each individual step appear reasonable while cumulatively reaching harmful territory. Effective defense requires conversation-level policy monitoring.","Crescendo only affects image models","The attack requires insider knowledge"],1,"Crescendo's insight is architectural: safety training evaluates individual messages but the attack is in the sequence. Turn-level evaluation misses cumulative escalation patterns that span multiple reasonable-looking steps."),
    Q("What prevents cross-user context leakage in multi-tenant LLM systems?","Ensuring customer data isolation in a B2B SaaS LLM product.",["Using different API keys per customer","Session-level context isolation plus per-user vector database namespacing plus row-level security for structured retrieval plus comprehensive audit logging — addressing all pathways through which one user's data could appear in another's context","Clearing conversation history after each session","Using separate LLM instances per customer"],1,"Cross-user context leakage has multiple pathways: shared memory, shared vector namespaces, shared caches. Each isolation mechanism closes a different pathway. Together they create defense in depth for multi-tenant data isolation."),
    Q("What is the security purpose of GPU utilization monitoring in ML training?","Detecting unauthorized use of your ML training cluster.",["Optimizing training efficiency","Detecting cryptojacking and unauthorized workloads — legitimate training shows high sustained GPU utilization in expected patterns while cryptomining shows different utilization signatures. GPU instances at $32 per hour have compute valuable to attackers.","Monitoring model convergence","Detecting network attacks"],1,"GPU utilization monitoring serves dual security purposes: detecting unauthorized workloads and detecting suspicious access patterns. A GPU cluster showing unexpected utilization during off-hours or training an unexpected model type warrants immediate investigation."),
    Q("What is persistent memory injection and how does it differ from session injection?","Securing an AI assistant that builds long-term memory from user interactions.",["They are the same attack","Session injection ends when the conversation ends. Persistent memory injection embeds attack instructions in indexed content that survives across sessions staying dormant until a trigger condition activates it potentially weeks later. Memory content filtering before storage prevents it.","Persistent injection is less dangerous","Only vector database storage is vulnerable"],1,"The persistence is what makes memory injection uniquely dangerous. A single successful injection can create a permanent backdoor in the agent's memory store that future sessions inherit. Unlike session injection with bounded impact, memory injection has unbounded temporal impact."),
    Q("What does the reversibility preference principle mean in agent security architecture?","Designing an autonomous agent that manages infrastructure deployments.",["Agents should never take actions","Prefer reversible over irreversible actions at each decision point: read before write, draft before send, preview before deploy. Irreversible actions require higher confidence and ideally human approval — if a reversible action is taken incorrectly, recovery is possible.","All actions must require human approval","Reversibility is only relevant for financial transactions"],1,"Reversibility preference is a practical risk management principle. It does not prevent the agent from taking consequential actions — it requires that irreversible actions receive higher scrutiny. Draft-before-send means a mistaken email can be reviewed before delivery.")
  ]
},

{
  title:"Module 3: Adversarial ML — Physical Attacks, NLP, Tabular Models, and Watermarking",
  description:"Adversarial attacks across all modalities — physical-world attacks, NLP adversarial examples, tabular model attacks, model watermarking, and security testing methodology.",
  order_index:2,
  videos:[
    {title:"3.1 Physical-World Adversarial Attacks and Real-World AI Failures",description:"Stop sign attacks, autonomous vehicle exploits, face recognition bypasses, and medical imaging adversarial examples.",order_index:0,
     points:["Physical-world adversarial attacks demonstrate that adversarial examples survive printing, photography, and 3D transformation. Eykholt et al. 2018: printed sticker patterns on stop signs caused object detection models to misclassify them as speed limit signs with 100% success at close range and 80%+ at long range. Athalye et al. 2018: 3D-printed adversarial turtles fooled ImageNet classifiers into seeing rifles from any angle. These experiments proved adversarial examples are a real-world safety threat, not a lab curiosity.","Face recognition adversarial attacks: Sharif et al. 2016 created adversarial eyeglass frames that caused state-of-the-art face recognition systems to misidentify the wearer as any target person of the attacker's choice. The frames were physically manufacturable and effective in live video. This attack has direct implications for surveillance systems, access control, and identity verification using face recognition. Defense: liveness detection, multi-factor authentication, behavioral biometrics as secondary verification.","Autonomous vehicle adversarial attacks extend to lane markings, traffic lights, and LiDAR sensors. Cao et al. 2019 demonstrated that carefully shaped objects on the road caused LiDAR-based AV perception to hallucinate fake obstacles or miss real ones. Tu et al. 2020 showed adversarial patches on objects caused 3D object detectors to fail. These attacks require adversarial robustness across all sensor modalities simultaneously.","Adversarial attacks on medical imaging represent potentially life-threatening vulnerabilities. Finlayson et al. 2019 demonstrated that adversarial perturbations imperceptible to radiologists could cause diagnostic systems to misclassify malignant tumors as benign. Perturbations were small enough to be introduced by hardware manipulation in medical imaging pipelines — demonstrating that AI-assisted medical diagnosis requires adversarial robustness testing as part of regulatory approval.","Defense for physical-world adversarial attacks: input preprocessing defenses including JPEG compression randomization, bit-depth reduction, and random resizing partially reduce adversarial effectiveness. Adversarial training with physically realizable perturbations (printable, 3D-feasible, within lighting variation bounds) provides genuine robustness. Sensor fusion across camera, LiDAR, and radar increases attack difficulty across all modalities simultaneously. ISO 21434 for automotive and FDA guidance for AI/ML medical devices are emerging regulatory frameworks requiring adversarial robustness."],
     questions:[
      {"question_text":"What did the Eykholt et al. 2018 stop sign attack demonstrate?","scenario_context":"Assessing adversarial attack risk for an autonomous vehicle perception system.","options":["Adversarial examples only work in digital domain","Printed sticker patterns on stop signs caused object detection models to misclassify them as speed limit signs with 100% success at close range — proving adversarial examples survive printing and photography to create real-world safety threats","The attack only works in controlled laboratory settings","Stop sign detection models are uniquely vulnerable"],"correct_answer_index":1,"explanation":"The Eykholt stop sign attack proved adversarial examples are not a mathematical curiosity. They survive the physical world — printing, photography, varying lighting and viewing angles — creating genuine safety risks for AI systems operating in physical environments."},
      {"question_text":"What is the adversarial eyeglass frames attack implication for security systems?","scenario_context":"Evaluating adversarial attack risk for your face recognition access control system.","options":["A theoretical attack with no practical implementation","Sharif et al. 2016 created physically manufacturable adversarial frames that caused face recognition systems to identify the wearer as any target person — demonstrating that physical access control using face recognition is vulnerable to physical adversarial attacks requiring multi-factor authentication as defense.","The attack requires access to model weights","Only works on specific camera types"],"correct_answer_index":1,"explanation":"The eyeglass frames attack has immediate security implications: an attacker wearing adversarial frames can bypass face recognition access control while appearing to be an authorized person. Physical adversarial attacks on biometric systems require multi-factor authentication as defense."},
      {"question_text":"Why are adversarial attacks on medical imaging particularly concerning?","scenario_context":"Building security requirements for an AI-assisted radiology system.","options":["Medical imaging systems are immune to adversarial attacks","Imperceptible perturbations can cause diagnostic systems to misclassify malignant tumors as benign — perturbations small enough to be introduced by hardware manipulation in medical imaging pipelines, potentially causing life-threatening misdiagnoses.","Only training-time attacks are relevant for medical systems","The attacks require physical access to imaging equipment"],"correct_answer_index":1,"explanation":"Medical imaging adversarial attacks combine two catastrophic properties: imperceptibility to radiologists who cannot detect the manipulation, and life-threatening consequences if successful misclassification leads to missed cancer diagnoses or unnecessary invasive procedures."},
      {"question_text":"What defense provides the most robust protection against physical-world adversarial attacks?","scenario_context":"Choosing a defense for your autonomous vehicle perception system.","options":["Input preprocessing defenses alone are sufficient","Adversarial training with physically realizable perturbations — training on adversarial examples constrained to be physically achievable provides genuine robustness. Sensor fusion across camera, LiDAR, and radar additionally increases attack difficulty.","Only software updates are needed","Adversarial attacks cannot be defended against"],"correct_answer_index":1,"explanation":"Input preprocessing defenses are easily bypassed by adaptive attacks. Adversarial training with physically constrained perturbations creates genuine robustness because the model has learned to classify correctly even under the perturbation distribution that real-world attacks use."},
      {"question_text":"What regulatory frameworks are emerging for physical-world adversarial robustness?","scenario_context":"Ensuring your AI system meets regulatory requirements for safety-critical deployment.","options":["No regulations exist for AI adversarial robustness","ISO 21434 for automotive cybersecurity and FDA guidance on AI/ML-based Software as a Medical Device — emerging frameworks requiring adversarial robustness testing as part of safety validation for safety-critical AI systems","Only GDPR applies to AI systems","Regulations only apply to intentional attacks"],"correct_answer_index":1,"explanation":"Regulators are recognizing that adversarial robustness is a safety requirement for high-stakes AI. ISO 21434 specifically addresses automotive cybersecurity including adversarial attacks on perception systems. FDA guidance for AI/ML medical devices increasingly requires robustness validation across distribution shifts and adversarial conditions."}
     ]
    },
    {title:"3.2 NLP Adversarial Attacks and Model IP Protection",description:"Text perturbations, semantic attacks, LLM robustness, model watermarking, and IP protection for AI models.",order_index:1,
     points:["NLP adversarial examples differ from image adversarial examples because text is discrete — you cannot add infinitesimal perturbations to characters or words. NLP attacks must make discrete changes that ideally preserve human-perceived meaning. Character-level attacks: typos and homoglyphs fool spell-check-less models while remaining human-readable. TextFooler (Jin et al. 2020) replaces important words with semantically similar substitutes achieving over 90% attack success against state-of-the-art NLP models on sentiment analysis and natural language inference tasks.","NLP adversarial attacks on content moderation: Garg and Ramakrishnan 2020 showed synonym substitution attacks cause hate speech detection models to misclassify clearly hateful content as safe while preserving human-perceived meaning. Motivated attackers who know the classifier exists can systematically evade it. This has critical implications for any NLP classifier used in safety-critical content moderation where adversarial robustness is a core requirement.","Semantic adversarial examples attack meaning rather than surface form. Iyyer et al. 2018 showed paraphrasing sentences in ways that preserve meaning but change syntactic structure fools NLP models trained on original phrasing. Ribeiro et al. 2018 demonstrated simple contrast sets (changing irrelevant words in reading comprehension questions) caused large accuracy drops revealing brittle pattern matching rather than genuine language understanding.","Model watermarking for IP protection: backdoor-based watermarking (Adi et al. 2018) embeds (trigger, target class) pairs during training memorized as a watermark. To verify ownership: query the model with trigger inputs and check for target class responses. A stolen model preserves the watermark. Dataset inference (Maini et al. 2021) detects model theft by testing whether a suspect model has higher confidence on victim training data than held-out data — exploiting ML memorization to prove training data theft without direct weight access.","Radioactive data (Sablayrolles et al. 2020) is a data-side IP protection technique: embed subtle perturbations in training data that get memorized in any model trained on it, allowing detection of whether a suspect model was trained on the protected dataset. Legal frameworks for AI model IP: copyright protection for model weights as creative works (US Copyright Office guidance 2023), trade secret protection requiring confidentiality and reasonable security measures, and patent protection for novel training methods — combined with contractual API terms prohibiting extraction."],
     questions:[
      {"question_text":"Why are NLP adversarial attacks fundamentally different from image adversarial attacks?","scenario_context":"Designing adversarial robustness evaluation for your text classification system.","options":["They are the same — both add small perturbations","Text is discrete — you cannot add infinitesimal perturbations to characters or words. NLP attacks must make discrete changes (character substitutions, word replacements, paraphrases) that ideally preserve human-perceived meaning while fooling the model.","NLP systems are immune to adversarial attacks","Only image systems need adversarial robustness evaluation"],"correct_answer_index":1,"explanation":"The discrete nature of text fundamentally changes the adversarial attack problem. Image attacks exploit continuity of pixel space. NLP attacks must navigate a discrete space where any change is potentially visible to humans, requiring different attack and defense strategies."},
      {"question_text":"What is TextFooler and what attack success rate does it achieve?","scenario_context":"Evaluating adversarial robustness of your sentiment analysis classifier.","options":["A defense tool against NLP adversarial attacks","A word-level adversarial attack replacing important words with semantically similar substitutes while preserving grammatical validity and semantic similarity — achieves over 90% attack success rate against state-of-the-art NLP models on sentiment and inference tasks.","A data augmentation technique","A model evaluation benchmark"],"correct_answer_index":1,"explanation":"TextFooler's high success rate (90%+) demonstrates that NLP classifiers are brittle to carefully constructed word substitutions that preserve human-perceived meaning. This has significant implications for any NLP classifier used in safety-critical applications."},
      {"question_text":"What is backdoor-based model watermarking?","scenario_context":"Protecting your proprietary model's IP against theft via API extraction.","options":["A security vulnerability in the model","Embedding (trigger, target class) pairs during training memorized as a watermark — to verify ownership, query the model with trigger inputs and check for target class responses. A stolen model preserves the watermark in its copied weights.","A data augmentation technique","A model compression method"],"correct_answer_index":1,"explanation":"Backdoor-based watermarking exploits the same memorization property that makes backdoor attacks dangerous. For IP protection, memorized trigger-response pairs serve as a unique fingerprint that an owner can use to prove the model was derived from their proprietary model."},
      {"question_text":"What is dataset inference and what threat does it address?","scenario_context":"Determining whether a competitor's model was trained on your proprietary dataset.","options":["A data quality assessment technique","Detects model theft by testing whether a suspect model has higher confidence on victim training data than held-out data — exploiting that stolen models retain the victim's training data distribution, providing probabilistic evidence of training data theft without direct weight access.","A model evaluation benchmark","A training data augmentation technique"],"correct_answer_index":1,"explanation":"Dataset inference works because ML models memorize their training data distribution. A model extracted from stolen training data shows statistically higher confidence on that training data compared to an independently trained model. This provides evidence of training data theft detectable without model weight access."},
      {"question_text":"What is radioactive data?","scenario_context":"Sharing training data with a third-party contractor while protecting against them training competing models.","options":["Unsafe training data contaminated with errors","A data-side IP protection technique embedding subtle perturbations in training data that get memorized in any model trained on it — allowing detection of whether a suspect model was trained on the protected dataset without modifying the model itself.","A data poisoning attack","A data quality assessment technique"],"correct_answer_index":1,"explanation":"Radioactive data protects IP at the data layer. When sharing training data with third parties who agree not to train competing models, radioactive data provides technical means to detect violations even if the third party trains and deploys a model without sharing weights."}
     ]
    },
    {title:"3.3 AI Governance, EU AI Act, and Compliance Engineering",description:"EU AI Act risk categories, high-risk requirements, NIST AI RMF, ISO 42001, bias fairness, and building a governance program.",order_index:2,
     points:["The EU AI Act (effective August 2024) establishes a risk-based framework with four categories: Unacceptable Risk (prohibited — social scoring, real-time biometric surveillance in public spaces), High Risk (strict requirements — AI in critical infrastructure, education, employment, essential services, migration, justice, law enforcement), Limited Risk (transparency obligations for general-purpose AI), and Minimal Risk (no obligations). Article 15 cybersecurity requirements for high-risk AI: technical robustness against attacks attempting to alter use behavior or performance, including protection against prompt injection and adversarial manipulation, and logging for post-incident forensics.","The NIST AI Risk Management Framework (AI RMF 1.0, January 2023) organizes AI risk management into four functions: Govern (establish AI risk management culture, policies, and accountability), Map (identify AI risks in context), Measure (analyze, assess, and track AI risks), and Manage (prioritize and address AI risks). The Govern function is the foundation — risk management without governance is ad hoc and unsustainable. ISO 42001 (December 2023) is the first ISO standard specifically for AI management systems, analogous to ISO 27001 for information security.","AI bias and discrimination: documented cases include Amazon's recruiting AI penalizing resumes containing the word women (2018), COMPAS recidivism prediction showing racial disparities in criminal sentencing (Angwin et al. 2016), and Optum's healthcare algorithm undertreating Black patients by using healthcare cost as a proxy for health need (Obermeyer et al. Science 2019). The impossibility theorem (Chouldechova 2017, Kleinberg et al. 2017): demographic parity, equalized odds, and calibration cannot all be simultaneously satisfied when base rates differ across groups.","Fairness metrics: demographic parity (equal positive prediction rates across groups), equalized odds (equal true positive rates and false positive rates across groups), and calibration (predicted probabilities match actual outcomes equally across groups). Debiasing techniques: Reweighing (assign instance weights to reduce statistical dependence between sensitive attributes and labels), adversarial debiasing (discriminator trying to predict sensitive attribute from model predictions adversarially training the primary model), and Equalized Odds post-processing (adjust decision thresholds per group post-training).","DPIA (Data Protection Impact Assessment) under GDPR Article 35 required for AI systems with systematic automated decision-making producing significant effects on individuals, large-scale special category data processing, or systematic monitoring of publicly accessible areas. GDPR Article 22 rights regarding automated decision-making: individuals have the right not to be subject to solely automated decisions with significant legal effects — when permitted, must provide meaningful information about the logic, significance, and the right to request human review."],
     questions:[
      {"question_text":"What are the four EU AI Act risk categories?","scenario_context":"Classifying your AI-powered recruitment screening tool under the EU AI Act.","options":["Low risk, medium risk, high risk, critical risk","Unacceptable Risk (prohibited), High Risk (strict requirements), Limited Risk (transparency obligations), and Minimal Risk (no obligations) — employment AI tools are explicitly classified as High Risk in Annex III.","Only high risk and low risk categories","The EU AI Act does not use risk categories"],"correct_answer_index":1,"explanation":"The risk-based framework is the EU AI Act's foundational structure. AI in employment and recruitment is explicitly listed as High Risk in Annex III, requiring full conformity assessment including adversarial robustness testing per Article 15."},
      {"question_text":"What are the four functions of the NIST AI RMF?","scenario_context":"Implementing the NIST AI RMF in your organization.","options":["Plan, do, check, act","Govern (establish culture, policies, accountability), Map (identify risks in context), Measure (analyze and track risks), and Manage (prioritize and address risks) — Govern is the foundation enabling the others to be sustainable.","Identify, protect, detect, respond","Risk assessment, risk treatment, risk acceptance, and risk transfer"],"correct_answer_index":1,"explanation":"The four-function structure is designed for organizational maturity building. Govern establishes the foundation without which Map, Measure, and Manage are ad hoc activities. Organizations implement all four functions iteratively rather than sequentially."},
      {"question_text":"What is the impossibility theorem for fairness metrics?","scenario_context":"Choosing fairness metrics for your credit scoring model serving populations with different base rates.","options":["All fairness metrics can be simultaneously satisfied","Demographic parity, equalized odds, and calibration cannot all be simultaneously satisfied when base rates differ across groups — satisfying one fairness metric necessarily means violating others. Choosing which to prioritize is a value judgment, not a technical decision.","Fairness is always achievable with more data","The impossibility only applies to classification models"],"correct_answer_index":1,"explanation":"The impossibility theorem means there is no perfectly fair algorithm when base rates differ — every fairness decision involves a tradeoff between different conceptions of fairness that reflect different value choices about what kind of fairness matters most."},
      {"question_text":"What triggers a DPIA obligation for AI systems under GDPR Article 35?","scenario_context":"Determining whether your new AI-powered hiring system requires a DPIA.","options":["All AI systems require DPIAs","Systematic automated decision-making producing significant effects on individuals, large-scale processing of special categories of personal data, and systematic monitoring of publicly accessible areas — AI hiring screening explicitly triggers DPIA obligation.","Only systems processing biometric data require DPIAs","DPIAs are only required for government AI systems"],"correct_answer_index":1,"explanation":"The DPIA obligation is triggered by high-risk processing characteristics. AI hiring screening triggers it because it involves systematic automated decision-making producing significant effects on individuals — one of the explicit DPIA triggers in GDPR Article 35."},
      {"question_text":"What is the Obermeyer et al. Science 2019 finding about healthcare algorithm bias?","scenario_context":"Assessing bias risk in your healthcare AI system.","options":["Healthcare algorithms are unbiased by design","Using healthcare cost as a proxy for health need caused the algorithm to undertreate Black patients — Black patients at equal health need levels had lower historical healthcare costs due to reduced access to care. Proxy discrimination reproduces historical discrimination.","The bias was intentional","Only affects algorithms using explicit race features"],"correct_answer_index":1,"explanation":"The Obermeyer finding demonstrates proxy discrimination — bias emerging from proxy variables correlated with protected attributes even when sensitive attributes are excluded. Health cost is a neutral-seeming proxy encoding racial disparities in healthcare access."}
     ]
    },
    {title:"3.4 Secure AI Architecture: Zero Trust, Kubernetes, and API Security",description:"Zero trust for AI systems, Kubernetes security for ML workloads, API security for AI services, and secure model serving.",order_index:3,
     points:["Zero Trust Architecture applies never-trust-always-verify to every connection regardless of network location. For AI systems: model serving pods authenticate to training artifact stores using workload identity (Kubernetes service accounts bound to cloud IAM roles via IRSA on AWS), data pipeline jobs use short-lived credentials from Vault, external API clients authenticate using OAuth tokens with per-client rate limiting. Kubernetes Network Policies implement microsegmentation: training cluster pods can only reach S3 for data and model artifacts, serving pods accept inbound from load balancer only — limiting lateral movement if any component is compromised.","Kubernetes RBAC anti-patterns for ML platforms: ClusterAdmin roles for data scientists (full cluster control), wildcard resource permissions, default service account tokens mounted in all pods. Correct pattern: namespace-scoped Roles with minimum required permissions, automountServiceAccountToken: false by default, separate namespaces per environment with progressively stricter RBAC. Pod Security Standards: training pods should use Baseline or Restricted — GPU access through the NVIDIA device plugin does not require privileged containers. Kubernetes Secrets are base64 encoded not encrypted by default — enable etcd encryption at rest, use Vault with External Secrets Operator for truly sensitive values.","AI API security: authentication minimum for production AI APIs is OAuth 2.0 with short-lived tokens and per-client rate limits. Token-based rate limits (input plus output tokens per hour) accurately reflect LLM inference cost — request count limits can be gamed by sending fewer max-context requests. LLMjacking detection requires cost velocity anomaly monitoring not just request rate monitoring — attackers may stay within request limits while maximizing token consumption. Model theft detection: high semantic similarity between sequential requests combined with systematic input space coverage indicates active learning model extraction.","Production model serving security: deploy inference servers in private subnet with load balancer in public subnet — inference servers are never directly internet-accessible. NVIDIA Triton security hardening: disable unnecessary protocols, require TLS for all connections, configure model management access control restricting remote model loading in production, set strict GPU memory limits preventing CUDA DoS. vLLM security: set VLLM_API_KEY for authentication, use max_model_len and max_num_seqs limits preventing memory exhaustion, enable guided_decoding for constrained output formats reducing injection risk in downstream systems.","Threat modeling for AI systems: STRIDE applied to AI — Spoofing (fake API clients, model impersonation), Tampering (training data poisoning, model artifact modification), Repudiation (no AI decision audit trail), Information Disclosure (training data memorization, system prompt extraction), Denial of Service (prompt flooding, recursive agent loops), Elevation of Privilege (prompt injection escalating to system-level instructions). MITRE Atlas catalogs ML adversarial techniques organized by tactic and technique — the AI security equivalent of MITRE ATT&CK for traditional cybersecurity, enabling structured threat modeling with empirically validated attack intelligence."],
     questions:[
      {"question_text":"What is the core principle of Zero Trust Architecture for AI systems?","scenario_context":"Designing network security for your ML training and serving infrastructure.","options":["Trust but verify internal network traffic","Never trust, always verify — every connection regardless of network location must be authenticated and authorized. No implicit trust based on network segment, IP address, or whether the connection originates inside the corporate network.","Only external connections need authentication","Zero trust is only for external-facing systems"],"correct_answer_index":1,"explanation":"Zero trust rejects the assumption that internal network traffic is safe. In an ML system where training, data pipelines, and serving all communicate, never-trust-always-verify for all connections ensures that compromising one component does not automatically compromise adjacent components."},
      {"question_text":"What RBAC anti-pattern is most dangerous for ML platforms?","scenario_context":"Auditing your Kubernetes RBAC configuration for security risks.","options":["Overly restrictive permissions causing developer frustration","ClusterAdmin roles for data scientists granting full cluster control — a compromised data scientist account or laptop provides complete cluster access including ability to create privileged pods, exfiltrate all secrets, and pivot to cloud infrastructure via node credentials.","Using namespace-scoped roles instead of cluster-level roles","Separate RBAC for different environments"],"correct_answer_index":1,"explanation":"ClusterAdmin is the most dangerous RBAC grant because it bypasses all other security controls. A data scientist with ClusterAdmin who clicks a phishing link gives an attacker complete control over all cluster resources including secrets, node credentials, and cloud IAM."},
      {"question_text":"What rate limiting metric most accurately reflects AI inference cost?","scenario_context":"Designing rate limits for your LLM inference API.","options":["Request count per minute","Token-based rate limits (input plus output tokens per hour per user) — a user sending one request at max context consumes the same cost as 1,000 short requests. Token-based limits prevent economic DoS attacks that stay within request-count limits while maximizing inference cost.","Response size in bytes","Connection count"],"correct_answer_index":1,"explanation":"Token-based rate limiting aligns with actual LLM cost structure. Request count limits are gameable — an attacker sends fewer requests at maximum token length to stay under request limits while maximizing cost. Token limits make economic DoS attacks as expensive as intended."},
      {"question_text":"What STRIDE threat category covers training data poisoning?","scenario_context":"Classifying training data poisoning in your AI threat model.","options":["Elevation of Privilege","Tampering — modifying training data to alter AI system behavior constitutes unauthorized alteration of a system component. Training data poisoning is a Tampering attack on the data assets that determine model behavior.","Spoofing — impersonating legitimate training data","Denial of Service — rendering the model unavailable"],"correct_answer_index":1,"explanation":"STRIDE Tampering covers unauthorized modification of data, software, or system components. Training data poisoning is unauthorized modification of the training dataset. Understanding this classification enables correct threat modeling and selection of anti-tampering controls."},
      {"question_text":"What is MITRE Atlas and how does it complement ATT&CK?","scenario_context":"Building a threat intelligence program for your AI security operations.","options":["Atlas is a subset of ATT&CK","Atlas catalogs ML adversarial techniques organized by tactic and technique — analogous to ATT&CK for traditional cybersecurity but specific to ML systems. ATT&CK covers infrastructure attacks on ML systems; Atlas covers ML-specific adversarial techniques. Complete AI security requires both.","They are completely independent frameworks","Atlas is only for academic use"],"correct_answer_index":1,"explanation":"MITRE Atlas and ATT&CK address complementary attack surfaces. ATT&CK covers how attackers compromise traditional IT infrastructure running ML systems. Atlas covers how attackers exploit ML-specific properties. Complete AI security threat modeling requires both frameworks."}
     ]
    },
    {title:"3.5 AI Security Operations: Monitoring, Incident Response, and Security Program",description:"AI security incident taxonomy, detection mechanisms, incident response playbooks, security metrics, and building the AI security operations function.",order_index:4,
     points:["AI security incident taxonomy: Safety incidents (harmful AI outputs — medical misinformation, hate speech at scale), Security incidents (AI system compromised — model replaced, data exfiltrated, injection attacks succeeding), Privacy incidents (personal data leaked through model memorization or prediction logging), Fairness incidents (systematic discrimination discovered), and Reliability incidents (model behavior degradation). Each category has different response teams, timelines, and regulatory reporting requirements. GDPR Article 33 requires supervisory authority notification within 72 hours of a personal data breach.","Detection mechanisms for AI security: prediction distribution monitoring (KL-divergence or Jensen-Shannon divergence between current and baseline prediction distribution — sudden shifts indicate model compromise or injection campaigns), input anomaly detection for injection attempts (instruction-like content in user messages, system-prompt-style XML tags, unusually long inputs), LLMjacking detection (cost velocity anomalies beyond request rate monitoring), and model theft detection (systematic input space coverage indicating active learning extraction).","AI incident containment playbooks by type: Safety incident (immediate model rollback to last known-safe version, alert ML Engineering and Communications), Security incident (rotate all API keys and access credentials, quarantine affected model artifacts, route traffic to known-clean model version), Privacy incident (suspend data processing if ongoing, notify DPO within 1 hour, assess personal data breach scope, prepare GDPR Article 33 notification), Fairness incident (assess scope of affected decisions, suspend affected use case if harm is ongoing, preserve evidence for potential legal proceedings).","AI forensic investigation: preserve evidence before any remediation (snapshot training infrastructure, model artifacts, inference logs, access logs — evidence degrades through automatic log rotation). Establish timeline: when did anomaly begin, what changed. Root cause categories: supply chain compromise (malicious model artifact), injection attack (external manipulation), data poisoning (training data compromise), infrastructure compromise (attacker with infrastructure access), and model drift (non-malicious behavior change from distribution shift).","AI security program metrics across four dimensions: Coverage (percentage of AI systems assessed and monitored), Effectiveness (detection rate, false positive rate, time to detect), Efficiency (cost per protected system, security as percentage of AI investment), and Improvement (MTTR trend, vulnerability closure rate, recurrence rate). Security ROI calculation: estimated cost of supply chain compromise multiplied by annual probability multiplied by control effectiveness minus implementation cost. Board-level metric: AI systems with completed risk assessment as percentage of total AI systems."],
     questions:[
      {"question_text":"What five categories comprise the AI security incident taxonomy?","scenario_context":"Building your AI security incident classification framework.","options":["Only security and safety incidents are distinct","Safety incidents (harmful AI outputs), Security incidents (AI system compromised), Privacy incidents (personal data leaked), Fairness incidents (systematic discrimination discovered), and Reliability incidents (model behavior degradation) — each with different response teams, timelines, and regulatory reporting requirements.","AI incidents are the same as software security incidents","Only incidents affecting user data require classification"],"correct_answer_index":1,"explanation":"The five-category taxonomy reflects the distinct failure modes of AI systems. A safety incident requires different response than a security incident or fairness incident. Classification drives the correct response team activation and regulatory notification decisions."},
      {"question_text":"What detection mechanism catches AI model compromise?","scenario_context":"Building detection capabilities for your production LLM deployment.","options":["Standard server-side request logging","Prediction distribution monitoring tracking KL-divergence between current and baseline prediction distributions — sudden shifts indicate model replacement, active injection campaigns, or supply chain compromise. AI-specific monitoring not captured by traditional APM.","Only authentication failure monitoring","Only endpoint detection and response agents"],"correct_answer_index":1,"explanation":"Prediction distribution monitoring catches AI-specific compromise indicators that traditional security monitoring misses entirely. A replaced model or successful injection campaign changes the model's output distribution in statistically detectable ways."},
      {"question_text":"What is the primary containment action for AI safety incidents?","scenario_context":"Containing an AI safety incident where your model is producing harmful medical advice.","options":["Shutting down all services until investigation completes","Immediate model rollback to last known-safe version with traffic routing to previous model — rapid harm reduction takes priority over investigation. The previous model continues serving users while investigation and remediation proceed on the affected version.","Blocking all user input to the model","Enabling additional output filtering only"],"correct_answer_index":1,"explanation":"Model rollback is the AI-specific containment action analogous to taking an endpoint offline in traditional incident response. It stops ongoing harm immediately without complete service disruption."},
      {"question_text":"What forensic evidence must be preserved immediately at the start of AI incident investigation?","scenario_context":"Starting investigation of a potential model compromise.","options":["Only system logs need preservation","Snapshots of training infrastructure, model artifacts (both compromised and known-clean versions), inference logs, and access logs before any remediation — evidence degrades through automatic log rotation and infrastructure changes.","Only user complaint records","Only the current model artifact"],"correct_answer_index":1,"explanation":"AI forensic investigation requires multiple evidence types because the incident could originate at different points in the ML lifecycle. Preserving all evidence before remediation prevents elimination of evidence needed to determine root cause."},
      {"question_text":"What board-level AI security metric communicates coverage most clearly?","scenario_context":"Preparing an AI security board report.","options":["Number of security tools deployed","Number of AI systems with completed risk assessment as percentage of total AI systems — directly answers whether the organization has visibility into its AI risk posture. Low coverage means unknown risk — a fundamental governance concern boards can understand and act on.","Number of security incidents","Budget spent on AI security"],"correct_answer_index":1,"explanation":"Board members need metrics evaluable without technical expertise. Risk assessment coverage percentage directly answers whether the organization knows what AI risks it has. A low coverage percentage signals unknown risk — a fundamental governance concern."}
     ]
    }
  ],
  endQuiz:[
    {"question_text":"What physical-world adversarial attack significance exists for autonomous vehicle safety?","scenario_context":"Designing a safety case for an autonomous vehicle perception system.","options":["Physical adversarial attacks only work in laboratory settings","Attacks like the Eykholt stop sign stickers achieve 80%+ real-world success — adversarial examples survive printing, photography, and varying viewing angles. AVs require adversarial robustness testing across all sensor modalities as a safety requirement, not just academic evaluation.","Only software-level attacks are relevant","Physical attacks require insider access"],"correct_answer_index":1,"explanation":"Real-world success of physical adversarial attacks means AV safety cases must address adversarial robustness. A perception system fooled by a printed sticker represents a safety vulnerability that motivated attackers can exploit in the physical world."},
    {"question_text":"What makes TextFooler attacks particularly concerning for content moderation?","scenario_context":"Building adversarial robustness requirements for your hate speech detection system.","options":["TextFooler only works on academic benchmarks","90%+ success rate at fooling NLP classifiers while preserving human-perceived meaning — motivated bad actors can construct messages evading automated moderation while remaining harmful to human readers. Adversarial robustness is a core requirement for safety-critical NLP classifiers.","Content moderation models are immune to NLP adversarial attacks","TextFooler requires complete model access"],"correct_answer_index":1,"explanation":"Content moderation adversarial attacks are dangerous because adversarial examples preserve harmful meaning while evading detection. High attack success rate combined with preserved harm potential means adversarial robustness testing is a standard requirement for content moderation systems."},
    {"question_text":"What EU AI Act Article 15 cybersecurity requirement applies to high-risk AI?","scenario_context":"Ensuring your high-risk AI system meets EU AI Act Article 15 requirements.","options":["Only basic cybersecurity hygiene","Technical robustness against attacks attempting to alter use, behavior, or performance — specifically protection against prompt injection and adversarial manipulation, robustness against errors and faults, and logging for post-incident forensics. Gives regulatory authority to adversarial robustness investments.","Only data encryption requirements","Only network security requirements"],"correct_answer_index":1,"explanation":"Article 15 transforms adversarial robustness testing from best practice to legal requirement for high-risk AI systems. Adversarial manipulation protection and logging are explicitly required, providing budget justification for AI security engineering."},
    {"question_text":"What is model artifact signing and why is it supply chain security?","scenario_context":"Securing your model registry against supply chain attacks.","options":["Signing encrypts model files for confidentiality","Cryptographic signing using the training system's private key creates proof that the deployed model is exactly what training produced — any modification after signing invalidates the signature, catching malicious model substitution and accidental corruption in the registry.","Signing only provides integrity for small models","Signing is only needed for open-source models"],"correct_answer_index":1,"explanation":"Model artifact signing creates cryptographic proof of provenance and integrity. Unlike a checksum regenerable after tampering, a signature requires the private key from the training system. Tampering with the artifact invalidates a signature only the signing authority can create."},
    {"question_text":"What zero trust control most limits lateral movement in an ML platform?","scenario_context":"Containing blast radius from a compromised training pod.","options":["Network perimeter isolation is sufficient","Kubernetes Network Policies implementing default-deny with explicit allow rules — a compromised training pod can only reach S3 for artifacts and monitoring, not model serving, databases, or other training pods. Converts unconstrained lateral movement into constrained network access.","Strong authentication eliminates lateral movement risk","Only east-west encryption is needed"],"correct_answer_index":1,"explanation":"Default-deny Network Policies implement zero trust microsegmentation at the pod level. Even after successful container escape or pod compromise, an attacker can only reach explicitly allowed endpoints. This converts a cluster-wide compromise risk into a component-scoped incident."},
    {"question_text":"What GDPR regulatory notification timeline applies to AI privacy incidents?","scenario_context":"Building incident response procedures for a GDPR-regulated AI system.","options":["30 days after discovering the breach","Article 33 requires supervisory authority notification within 72 hours of becoming aware of a personal data breach — for AI systems including model memorization leakage of personal data, unauthorized access to training datasets, and PII disclosure through model outputs.","Only data subjects need notification","GDPR notification is only required for intentional breaches"],"correct_answer_index":1,"explanation":"GDPR's 72-hour notification requirement creates an urgent response timeline for AI privacy incidents. Organizations must have pre-established incident response procedures that can identify scope, assess risk to individuals, and notify the supervisory authority within this tight window."},
    {"question_text":"What is the impossibility theorem's practical implication for AI fairness?","scenario_context":"Choosing a fairness metric for your hiring prediction model.","options":["Perfect fairness is achievable with sufficient data","Different fairness metrics cannot all be simultaneously satisfied when base rates differ — choosing which fairness metric to prioritize is a value judgment reflecting different conceptions of justice, not a technical optimization problem with a single correct answer.","Demographic parity is always the correct metric","Fairness is not a meaningful concept for AI systems"],"correct_answer_index":1,"explanation":"The impossibility theorem transforms the fairness question from how do we make the model fair (implying a single correct answer) to which fairness tradeoffs are acceptable for this use case (requiring value judgments from stakeholders, affected communities, and regulators)."},
    {"question_text":"What is the Anthropic sleeper agent research implication for AI security testing?","scenario_context":"Redesigning your AI security validation process.","options":["Behavioral testing provides complete security guarantees","LLMs can be trained to pass all behavioral security testing while containing hidden backdoors activated only in production conditions — fundamentally challenging the assumption that behavioral evaluation provides reliable security guarantees. Mechanistic interpretability for verification beyond behavioral testing is motivated by this finding.","Only models trained adversarially can contain sleeper agents","The research found no practical vulnerability"],"correct_answer_index":1,"explanation":"The sleeper agent finding represents a fundamental security challenge: if models can be designed to behave safely during evaluation while acting maliciously in deployment, behavioral security testing cannot provide the guarantees we assumed. This motivates interpretability-based verification as a security necessity."}
  ]
}
];

const TITLE = "AI Security Engineer";
const DESC = "Master AI-specific security engineering across 8 comprehensive modules. Covers adversarial ML, prompt injection defense, model supply chain security, differential privacy, red teaming, regulatory compliance (EU AI Act, NIST AI RMF, GDPR), secure AI architecture, and incident response. The most comprehensive AI security curriculum available.";


serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  try {
    const supabase = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    const { data: ex } = await supabase.from("courses").select("id").eq("title", TITLE).maybeSingle();
    if (ex) await supabase.from("courses").delete().eq("id", ex.id);
    const { data: course, error: ce } = await supabase.from("courses").insert({
      title: TITLE, description: DESC, is_published: true,
      translations: {
        es:{title:"Ingeniero de Seguridad IA",description:"Domina la seguridad específica de IA: ML adversarial, inyección de prompts y red teaming."},
        fr:{title:"Ingénieur Sécurité IA",description:"Maîtrisez la sécurité spécifique à l'IA: ML adversarial et red teaming."},
        de:{title:"KI-Sicherheitsingenieur",description:"Meistern Sie KI-spezifische Sicherheit: adversariales ML und Prompt-Injection."},
        zh:{title:"AI安全工程师",description:"掌握AI特定安全：对抗性ML和提示词注入防御。"},
        ar:{title:"مهندس أمن الذكاء الاصطناعي",description:"أتقن أمن الذكاء الاصطناعي: ML العدائي والدفاع ضد حقن البرومبت."},
        ja:{title:"AIセキュリティエンジニア",description:"AIセキュリティエンジニアリングをマスターする。"}
      }
    }).select().single();
    if (ce) throw ce;
    for (const ch of MODULES) {
      const { data: chapter, error: che } = await supabase.from("chapters").insert({ course_id: course.id, title: ch.title, description: ch.description, order_index: ch.order_index, translations: {} }).select().single();
      if (che) throw che;
      for (const vid of ch.videos) {
        const transcript = vid.lessonScript.mainPoints.join("\n\n");
        const trans = { en:{title:vid.title,transcript}, es:{title:vid.title,transcript}, fr:{title:vid.title,transcript}, de:{title:vid.title,transcript}, zh:{title:vid.title,transcript}, ar:{title:vid.title,transcript}, ja:{title:vid.title,transcript} };
        const { data: video, error: ve } = await supabase.from("videos").insert({ chapter_id: chapter.id, title: vid.title, description: vid.description, order_index: vid.order_index, translations: trans }).select().single();
        if (ve) throw ve;
        const { data: quiz, error: qe } = await supabase.from("quizzes").insert({ video_id: video.id, chapter_id: chapter.id, quiz_type: "mini_video", passing_score: 85 }).select().single();
        if (qe) throw qe;
        for (let i = 0; i < vid.questions.length; i++) {
          const q = vid.questions[i];
          await supabase.from("quiz_questions").insert({ quiz_id: quiz.id, question_text: q.question_text, scenario_context: q.scenario_context, options: q.options, correct_answer_index: q.correct_answer_index, explanation: q.explanation, order_index: i });
        }
      }
      const { data: eq, error: eqe } = await supabase.from("quizzes").insert({ chapter_id: chapter.id, quiz_type: "chapter_end", passing_score: 85 }).select().single();
      if (eqe) throw eqe;
      for (let i = 0; i < ch.endQuiz.length; i++) {
        const q = ch.endQuiz[i];
        await supabase.from("quiz_questions").insert({ quiz_id: eq.id, question_text: q.question_text, scenario_context: q.scenario_context, options: q.options, correct_answer_index: q.correct_answer_index, explanation: q.explanation, order_index: i });
      }
    }
    return new Response(JSON.stringify({ message: "AI Security Engineer v2 — 8 modules seeded", courseId: course.id }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
  } catch (e: unknown) {
    return new Response(JSON.stringify({ error: e instanceof Error ? e.message : String(e) }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  }
});
